  overtime:{intro:'Calculate your overtime rate, regular earnings, extra pay, and total gross pay. Choose weekly or California-style daily overtime rules and the multiplier that applies.',body:otBody,seoTitle:'Overtime Calculator: Calculate Overtime Pay & Hourly Rate',description:'Calculate overtime pay, rates, regular earnings, and total gross pay from your hourly wage, overtime hours, and multiplier — weekly or California daily rules.',schema:toolSchemas('Overtime Calculator',otFaq)},
  paycheck:{intro:'Estimate gross and take-home pay from hourly pay or annual salary, with an optional state tax estimate. Include overtime, pay frequency, filing status, and optional deductions.',body:checkBody,seoTitle:'Paycheck Calculator: See Your Take-Home Pay Per Check',description:'See exactly what lands in your account each paycheck: gross pay minus federal tax, FICA, state tax, and your deductions, overtime included. Free, no sign-up.',schema:toolSchemas('Paycheck Calculator',checkFaq)},
  'salary-comparison':{intro:'Compare two job offers by salary, bonus, 401(k) match, health premiums, work hours, paid time off, and commute time — and see which one pays more for every hour it takes from your week.',body:compareBody,seoTitle:'Job Offer Comparison Calculator: True Pay Per Hour',description:'Compare two job offers on salary, bonus, 401(k) match, hours, commute, and PTO. See which pays more per hour of committed time. Free, no sign-up.',schema:toolSchemas('Salary Comparison Calculator',compareFaq)},
  'salary-increase':{intro:'See a pay change as a percentage and as an annual, monthly, weekly, and hourly amount. Start from the new pay or from the raise percentage. Works for annual salaries and hourly wages.',body:raiseBody,seoTitle:'Pay Raise Calculator: New Salary & Raise Percentage',description:'A 5% raise on $50,000 adds $2,500 a year. Calculate your new salary from a raise percentage or a dollar amount — per year, month, week, and hour. Free.',schema:toolSchemas('Salary Increase Calculator',raiseFaq)},
  'freelance-rate':{intro:'Estimate a billable hourly rate that covers your income goal, business expenses, tax reserve, and profit margin — based on the hours you can actually bill, including your day rate.',body:freelanceBody,seoTitle:'Freelance Rate Calculator: Find Your Target Hourly Rate',description:'Set a freelance hourly rate that covers your income goal, business expenses, tax reserve, and profit margin, based on your realistic billable hours.',schema:toolSchemas('Freelance Rate Calculator',freelanceFaq)}
